import React, { useState, useEffect } from 'react';

interface ClientStats {
  count: number;
  connected: number;
  available?: number;
  busy?: number;
}

interface ClientsStatsData {
  stats_by_type: {
    bot: ClientStats;
    worker: ClientStats;
    worker_api: ClientStats;
    stream_hub: ClientStats;
    monitor: ClientStats;
    admin: ClientStats;
  };
  total_clients: number;
  timestamp: string;
}

export const ClientsView: React.FC = () => {
  const [clientsData, setClientsData] = useState<ClientsStatsData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshInterval, setRefreshInterval] = useState<number>(5000);
  const [detailedView, setDetailedView] = useState<boolean>(false);
  const [detailedData, setDetailedData] = useState<any>(null);

  useEffect(() => {
    const fetchClientsData = async () => {
      try {
        setLoading(true);
        const response = await fetch('/dashboard/api/clients/detailed');
        if (!response.ok) {
          throw new Error(`Помилка HTTP: ${response.status}`);
        }
        const data = await response.json();
        setClientsData(data);
        if (detailedView) {
          setDetailedData(data.clients_by_type);
        }
        setError(null);
      } catch (err) {
        setError(`Помилка отримання даних: ${err instanceof Error ? err.message : String(err)}`);
      } finally {
        setLoading(false);
      }
    };

    fetchClientsData();

    // Встановлення інтервалу оновлення
    const interval = setInterval(fetchClientsData, refreshInterval);
    return () => clearInterval(interval);
  }, [refreshInterval, detailedView]);

  // Функція для відображення статусу
  const renderStatus = (count: number, connected: number) => {
    if (count === 0) return <span className="text-gray-400">Немає клієнтів</span>;
    if (connected === 0) return <span className="text-red-500">Усі відключені</span>;
    if (connected === count) return <span className="text-green-500">Усі підключені</span>;
    return <span className="text-yellow-500">{connected} з {count} підключено</span>;
  };

  // Функція для відображення статусу воркера
  const renderWorkerStatus = (stats: ClientStats) => {
    if (stats.count === 0) return <span className="text-gray-400">Немає воркерів</span>;
    if (stats.connected === 0) return <span className="text-red-500">Усі відключені</span>;

    return (
      <div className="flex flex-col">
        <span className={stats.connected === stats.count ? "text-green-500" : "text-yellow-500"}>
          {stats.connected} з {stats.count} підключено
        </span>
        {stats.available !== undefined && stats.busy !== undefined && stats.connected > 0 && (
          <span className="text-xs mt-1">
            <span className="text-green-500">{stats.available} вільно</span> / 
            <span className="text-blue-500"> {stats.busy} зайнято</span>
          </span>
        )}
      </div>
    );
  };

  // Відображення картки для типу клієнта
  const renderClientTypeCard = (type: string, title: string, stats: ClientStats, icon: React.ReactNode) => {
    return (
      <div className="bg-white rounded-xl shadow-sm p-6 transition-all hover:shadow-md">
        <div className="flex items-start justify-between">
          <div>
            <h3 className="text-xl font-semibold text-secondary-900">{title}</h3>
            <div className="mt-2 text-lg font-bold text-secondary-800">
              {stats.count} <span className="text-sm font-normal text-secondary-500">всього</span>
            </div>
            <div className="mt-1">
              {type === 'worker' || type === 'worker_api' 
                ? renderWorkerStatus(stats) 
                : renderStatus(stats.count, stats.connected)}
            </div>
          </div>
          <div className="text-secondary-400">
            {icon}
          </div>
        </div>
      </div>
    );
  };

  // Відображення детальної інформації про клієнтів
  const renderDetailedClients = () => {
    if (!detailedData) return null;

    return (
      <div className="mt-6">
        <h3 className="text-lg font-semibold text-secondary-900 mb-3">Детальна інформація про клієнтів</h3>
        <div className="bg-white rounded-xl shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-secondary-200">
              <thead className="bg-secondary-50">
                <tr>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">ID</th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">Тип</th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">Статус</th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">IP адреса</th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">Активність</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-secondary-200">
                {Object.entries(detailedData).flatMap(([type, clients]) => 
                  Array.isArray(clients) ? clients.map((client: any) => (
                    <tr key={client.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-900">{client.id}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-900">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium 
                          ${type === 'bot' ? 'bg-purple-100 text-purple-700' : ''}
                          ${type === 'worker' ? 'bg-blue-100 text-blue-700' : ''}
                          ${type === 'worker_api' ? 'bg-green-100 text-green-700' : ''}
                          ${type === 'stream_hub' ? 'bg-orange-100 text-orange-700' : ''}
                          ${type === 'monitor' ? 'bg-yellow-100 text-yellow-700' : ''}
                          ${type === 'admin' ? 'bg-red-100 text-red-700' : ''}
                        `}>
                          {type === 'worker_api' ? 'API Worker' : 
                           type === 'stream_hub' ? 'Stream Hub' : 
                           type.charAt(0).toUpperCase() + type.slice(1)}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                          ${client.is_connected ? 'bg-success-100 text-success-800' : 'bg-error-100 text-error-800'}
                        `}>
                          {client.is_connected ? 'Активний' : 'Відключений'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-500">{client.ip || 'N/A'}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-500">
                        {client.last_activity ? new Date(client.last_activity).toLocaleString() : 'Ніколи'}
                      </td>
                    </tr>
                  )) : []
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  if (loading && !clientsData) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-pulse flex space-x-4">
          <div className="rounded-full bg-secondary-200 h-12 w-12"></div>
          <div className="flex-1 space-y-4 py-1">
            <div className="h-4 bg-secondary-200 rounded w-3/4"></div>
            <div className="space-y-2">
              <div className="h-4 bg-secondary-200 rounded"></div>
              <div className="h-4 bg-secondary-200 rounded w-5/6"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-error-50 border border-error-200 text-error-800 px-4 py-3 rounded relative" role="alert">
        <strong className="font-bold">Помилка!</strong>
        <span className="block sm:inline"> {error}</span>
        <div className="mt-2 text-sm">
          Спроба отримати дані з URL: <code className="bg-error-100 px-1">/dashboard/api/clients/detailed</code>
        </div>
      </div>
    );
  }

  if (!clientsData) {
    return <div>Немає даних про клієнтів</div>;
  }

  // Іконки для типів клієнтів
  const icons = {
    bot: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 9l3 3-3 3m5 0h3M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
      </svg>
    ),
    worker: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
      </svg>
    ),
    worker_api: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
      </svg>
    ),
    stream_hub: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
      </svg>
    ),
    monitor: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
      </svg>
    ),
    admin: (
      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5.121 17.804A13.937 13.937 0 0112 16c2.5 0 4.847.655 6.879 1.804M15 10a3 3 0 11-6 0 3 3 0 016 0zm6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
  };

  const { stats_by_type } = clientsData;

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-secondary-900">Статус клієнтів</h2>
        <div className="flex items-center space-x-4">
          <div className="flex items-center">
            <select 
              value={refreshInterval} 
              onChange={(e) => setRefreshInterval(parseInt(e.target.value))}
              className="block w-32 py-2 px-3 border border-secondary-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-primary-500 focus:border-primary-500 sm:text-sm"
            >
              <option value={2000}>2 секунди</option>
              <option value={5000}>5 секунд</option>
              <option value={10000}>10 секунд</option>
              <option value={30000}>30 секунд</option>
            </select>
          </div>
          <div>
            <button
              onClick={() => setDetailedView(!detailedView)}
              className={`py-2 px-4 border rounded-md shadow-sm text-sm font-medium 
                ${detailedView 
                  ? 'bg-primary-600 text-white border-primary-600 hover:bg-primary-700' 
                  : 'bg-white text-secondary-700 border-secondary-300 hover:bg-secondary-50'}`}
            >
              {detailedView ? 'Сховати деталі' : 'Показати деталі'}
            </button>
          </div>
        </div>
      </div>

      <div className="text-sm text-secondary-500 mb-8">
        Всього активних клієнтів: <span className="font-medium text-secondary-700">{clientsData.total_clients}</span>
        <span className="text-secondary-400 ml-2">
          Оновлено: {new Date(clientsData.timestamp).toLocaleTimeString()}
        </span>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {renderClientTypeCard('bot', 'Боти', stats_by_type.bot, icons.bot)}
        {renderClientTypeCard('worker', 'Воркери', stats_by_type.worker, icons.worker)}
        {renderClientTypeCard('worker_api', 'API Воркери', stats_by_type.worker_api, icons.worker_api)}
        {renderClientTypeCard('stream_hub', 'Stream Hub', stats_by_type.stream_hub, icons.stream_hub)}
        {renderClientTypeCard('monitor', 'Монітори', stats_by_type.monitor, icons.monitor)}
        {renderClientTypeCard('admin', 'Адміністратори', stats_by_type.admin, icons.admin)}
      </div>

      {detailedView && renderDetailedClients()}
    </div>
  );
};
